  END IF;

  -- 07. Introducción a la unidad: del auditor individual al programa de auditoría
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Doce auditorías y ninguna conclusión","texto":"Una planta de líquidos estériles hizo doce auditorías internas el año pasado. Cada una tuvo su informe, pero nadie las miró en conjunto: tres auditorías distintas encontraron el mismo problema de capacitación, el área de sistemas computarizados nunca se auditó y la auditoría al proveedor del vial se aplazó cuatro veces. Cada auditoría estaba bien hecha; lo que faltaba era un **programa** que les diera dirección, cobertura y seguimiento."},"objetivos":["Diferenciar una auditoría individual de un programa de auditoría.","Describir el ciclo de gestión del programa según ISO 19011:2026.","Reconocer las responsabilidades de quien gestiona el programa en una organización farmacéutica."],"conceptos":[{"icono":"CalendarClock","termino":"Programa de auditoría","definicion":"Conjunto de disposiciones para una o más auditorías planificadas para un periodo y con un propósito definido. Responde a qué se audita, cuándo, cómo, con quién y para qué."},{"icono":"FileText","termino":"Plan de auditoría","definicion":"Descripción de las actividades y los detalles de una auditoría concreta: fechas, agenda, alcance, criterios, equipo y logística. El programa contiene muchos planes."},{"icono":"UserCheck","termino":"Responsable del programa","definicion":"Persona o función que establece, implementa, hace seguimiento, revisa y mejora el programa. En una planta suele estar en aseguramiento de la calidad."},{"icono":"RefreshCw","termino":"Ciclo del programa","definicion":"La gestión del programa sigue la lógica PHVA: establecer objetivos y riesgos, implementar, hacer seguimiento, revisar y mejorar."}],"secciones":[{"titulo":"Del informe aislado a la visión del sistema","parrafos":["ISO 19011:2026 dedica un capítulo completo a **gestionar el programa de auditoría**, y otro a **realizar** cada auditoría. La diferencia importa: una auditoría bien ejecutada da una fotografía de un área en un momento; un programa bien gestionado da la película del sistema durante un periodo. Es el programa el que asegura que todos los capítulos de las BPM se cubran, que los procesos de mayor riesgo se auditen con más frecuencia y que los hallazgos repetidos se vean como lo que son: señales de una falla del sistema.","En el caso inicial, un programa habría detectado tres cosas: la **cobertura incompleta** (sistemas computarizados nunca auditados), la **recurrencia** (el mismo hallazgo de capacitación en tres áreas, que apunta al proceso de formación y no a cada área) y el **incumplimiento del calendario** (la auditoría al proveedor crítico aplazada sin evaluar el riesgo de no hacerla)."]},{"titulo":"El ciclo de gestión del programa","parrafos":["El ciclo arranca por **establecer los objetivos** del programa y **determinar y evaluar sus riesgos y oportunidades**. Luego se **establece el programa**: roles, competencias de quien lo gestiona, extensión, métodos y recursos. Después se **implementa**: para cada auditoría se definen objetivos, alcance y criterios, se eligen los métodos, se conforma el equipo, se asigna la responsabilidad al líder y se gestionan los resultados y los registros.","El programa no termina con la última auditoría del año. Se **hace seguimiento** a su cumplimiento y eficacia, y se **revisa y mejora**: ¿se lograron los objetivos?, ¿los hallazgos llevaron a acciones eficaces?, ¿las personas auditoras tuvieron la competencia necesaria?, ¿cambió algo en la organización que obligue a ajustar el programa? La edición 2026 refuerza que, en cada etapa, se decida también el **método**: en sitio, remoto o híbrido."]},{"titulo":"Quién gestiona el programa en una empresa farmacéutica","parrafos":["En la mayoría de laboratorios, el programa lo gestiona **aseguramiento de la calidad**, con el respaldo de la dirección técnica y de la alta dirección. Quien lo gestiona necesita conocer los principios y métodos de auditoría, las normas aplicables (BPM, BPL, servicio farmacéutico, ISO 9001 si aplica), los procesos de la organización y sus riesgos, y tener capacidad para coordinar personas de distintas áreas.","Sus responsabilidades incluyen proponer el programa a la dirección, conseguir los recursos, formar y evaluar a las personas auditoras, asegurar la independencia de cada equipo, consolidar los resultados y presentarlos en la **revisión por la dirección**, que ICH Q10 e ISO 9001 exigen. Un programa que nunca llega a la dirección pierde la palanca más importante para corregir problemas de fondo, como la falta de personal o de inversión en instalaciones."]}],"errores":[{"error":"Confundir el programa con un calendario de fechas.","correccion":"El programa incluye objetivos, riesgos, métodos, recursos, competencias, seguimiento y mejora."},{"error":"Aplazar auditorías sin evaluar el riesgo de no hacerlas.","correccion":"Todo cambio al programa se justifica por riesgo y queda documentado."},{"error":"No llevar los resultados a la revisión por la dirección.","correccion":"Presenta tendencias, recurrencias y necesidades de recursos en cada revisión."}],"comprueba":[{"pregunta":"¿Qué diferencia hay entre programa y plan de auditoría?","respuesta":"El programa organiza un conjunto de auditorías en un periodo con un propósito; el plan describe las actividades de una auditoría concreta."},{"pregunta":"¿Qué etapas tiene el ciclo de gestión del programa?","respuesta":"Establecer objetivos y riesgos, establecer el programa, implementarlo, hacer seguimiento y revisarlo y mejorarlo."},{"pregunta":"¿Por qué un hallazgo repetido en varias áreas importa al programa?","respuesta":"Porque indica una falla sistémica que debe atacarse en el proceso común y no área por área."}],"resumen":["El **programa** da dirección, cobertura y seguimiento; el **plan** organiza una auditoría.","La gestión del programa sigue el ciclo **PHVA** y decide también el método: en sitio, remoto o híbrido.","Los resultados del programa deben llegar a la **revisión por la dirección**."],"referencias":[{"cita":"ISO. ISO 19011:2026 Directrices para la auditoría de sistemas de gestión (4.ª edición, mayo de 2026; reemplaza a la ISO 19011:2018).","url":"https://www.iso.org/standard/19011"},{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"ISO. ISO 9001:2026 Sistemas de gestión de la calidad — Requisitos (6.ª edición, 16 de septiembre de 2026; reemplaza a la ISO 9001:2015).","url":"https://www.iso.org/standard/9001"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Ciclo PHVA ilustrado con un calendario anual de auditorías en el centro y flechas hacia la revisión por la dirección.","alt":"Ciclo de gestión del programa de auditoría"}],"keywords":["programa de auditoría iso 19011","diferencia entre programa y plan de auditoría","gestión del programa de auditoría","programa de autoinspección farmacéutica","responsable del programa de auditoría","iso 19011 capítulo 5"],"mapa":{"centro":"Gestión del programa","ramas":[{"titulo":"Planear","icono":"Target","nodos":["Objetivos del programa","Riesgos y oportunidades","Alcance y recursos"]},{"titulo":"Hacer","icono":"Workflow","nodos":["Asignar equipos","Definir métodos","Ejecutar las auditorías"]},{"titulo":"Verificar","icono":"Gauge","nodos":["Cumplimiento del calendario","Calidad de los informes","Desempeño de auditores"]},{"titulo":"Actuar","icono":"RefreshCw","nodos":["Revisar resultados","Ajustar el programa","Informar a la dirección"]}]},"caso":{"titulo":"El mismo hallazgo en tres áreas","contexto":"En el consolidado anual, el responsable del programa ve que las auditorías de producción, almacén y control de calidad registraron, cada una, un hallazgo menor por personal que operaba con procedimientos actualizados sin haber recibido la capacitación.","pregunta":"¿Qué conclusión corresponde al nivel del programa?","opciones":[{"texto":"Son tres hallazgos menores independientes; cada área debe capacitar a su gente.","correcta":false,"retro":"Visto por separado parece menor, pero la repetición en tres áreas revela una falla del proceso de gestión de cambios y capacitación."},{"texto":"Hay una falla sistémica en el vínculo entre control de cambios documental y capacitación; se escala, se analiza la causa en ese proceso y se ajusta el programa para auditarlo.","correcta":true,"retro":"Esta es la ventaja del programa: ver patrones que una auditoría individual no ve y dirigir la mejora a la causa común."},{"texto":"Se debe aumentar la frecuencia de auditoría en las tres áreas.","correcta":false,"retro":"Auditar más las áreas no corrige el proceso común que genera el problema."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: del auditor individual al programa de auditoría$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción a la unidad: del auditor individual al programa de auditoría$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 08. Establecer objetivos, alcance y recursos del programa de auditoría
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Un programa sin objetivo","texto":"Al preguntarle por los objetivos de su programa de auditoría, la jefa de aseguramiento de un laboratorio responde: «cumplir la autoinspección anual». Es un requisito, pero no un objetivo útil: no dice qué riesgos se quieren controlar, qué proveedores hay que evaluar antes de un lanzamiento ni qué preparación exige la renovación del certificado de BPM del próximo año. Sin objetivos claros, el programa no puede decidir qué auditar primero ni cuántos recursos pedir."},"objetivos":["Formular objetivos del programa de auditoría coherentes con la estrategia de calidad y los requisitos regulatorios.","Definir la extensión del programa: alcance, número, duración, frecuencia y métodos de las auditorías.","Estimar los recursos necesarios: personas competentes, tiempo, tecnología y presupuesto."],"conceptos":[{"icono":"Target","termino":"Objetivos del programa","definicion":"Lo que el programa debe lograr en el periodo: por ejemplo, verificar el cumplimiento de BPM en todas las áreas, preparar la renovación del certificado o calificar a los proveedores críticos antes de un lanzamiento."},{"icono":"Layers","termino":"Extensión del programa","definicion":"Cuántas auditorías, de qué alcance, con qué frecuencia, duración y método. Depende del tamaño, la complejidad y los riesgos de la organización."},{"icono":"Users","termino":"Recursos del programa","definicion":"Personas auditoras competentes, expertos técnicos, tiempo, viajes, herramientas tecnológicas para auditar a distancia y presupuesto."},{"icono":"Crosshair","termino":"Alcance de una auditoría","definicion":"Extensión y límites de una auditoría: procesos, áreas, productos, ubicaciones y periodo que cubre."}],"secciones":[{"titulo":"Cómo formular objetivos útiles","parrafos":["Los objetivos del programa se derivan de las necesidades de la organización y de sus partes interesadas: los requisitos de BPM y BPL, el calendario de certificaciones ante el INVIMA, la política y los objetivos de calidad, las quejas y desviaciones del último año, los cambios planeados (nuevas líneas, nuevos proveedores, nuevos sistemas computarizados) y las expectativas de clientes o socios. Un buen objetivo es concreto y verificable.","Ejemplos para un laboratorio: «Auditar en el año todos los capítulos de la guía de inspección de BPM, con al menos dos auditorías a las áreas de alto riesgo»; «Auditar en sitio, antes de junio, a los tres proveedores de principio activo del nuevo producto»; «Hacer en el tercer trimestre una autoinspección integral que sirva como autoevaluación para la renovación del certificado de BPM». Con objetivos así, cada auditoría del programa tiene una razón de ser."]},{"titulo":"La extensión del programa","parrafos":["La **extensión** traduce los objetivos en auditorías concretas. Para decidirla se consideran el tamaño y la complejidad de la planta, el número de procesos y formas farmacéuticas, los resultados de auditorías e inspecciones anteriores, el desempeño de los procesos (desviaciones, quejas, resultados fuera de especificación), los cambios en la organización y los riesgos para el paciente. Una planta de estériles con dos líneas nuevas no puede tener el mismo programa que un almacén de cosméticos.","Para cada auditoría se fija el alcance (áreas, procesos, periodo), la frecuencia, la duración aproximada y el **método**. La edición 2026 de ISO 19011 trata los métodos en sitio, remotos e híbridos como opciones que se eligen según el riesgo y la capacidad tecnológica del auditado: una revisión de registros de capacitación puede hacerse a distancia; la verificación de un área estéril casi siempre exige presencia física."]},{"titulo":"Recursos: el punto débil de muchos programas","parrafos":["Muchos programas fracasan por falta de recursos, no de voluntad. Para estimarlos se calcula cuántas horas de auditoría exige cada auditoría (preparación, ejecución, informe y seguimiento), cuántas personas auditoras competentes e independientes hay disponibles, si se necesitan expertos técnicos (por ejemplo, en sistemas de agua o en validación de software), cuánto cuestan los viajes a proveedores y qué herramientas se requieren para auditar a distancia de forma segura.","Con esa estimación, quien gestiona el programa lo presenta a la dirección. Si los recursos no alcanzan, la decisión de qué auditoría reducir o aplazar debe tomarse por **riesgo** y quedar documentada, nunca por comodidad. Formar auditores internos de distintas áreas es una forma eficiente de ampliar los recursos y, al mismo tiempo, de extender la cultura de calidad."]}],"errores":[{"error":"Usar «cumplir la autoinspección» como único objetivo.","correccion":"Formula objetivos concretos ligados a riesgos, certificaciones y cambios."},{"error":"Planear auditorías sin estimar horas ni personas.","correccion":"Calcula recursos por auditoría y preséntalos a la dirección."},{"error":"Elegir auditoría remota solo porque es más barata.","correccion":"Elige el método por riesgo y por lo que se necesita verificar."}],"comprueba":[{"pregunta":"Da un ejemplo de objetivo verificable de un programa de auditoría.","respuesta":"Auditar en sitio, antes de junio, a los tres proveedores de principio activo del nuevo producto."},{"pregunta":"¿Qué se define en la extensión del programa?","respuesta":"Alcance, número, frecuencia, duración y método de las auditorías."},{"pregunta":"¿Cómo se decide qué auditoría aplazar si faltan recursos?","respuesta":"Por riesgo, con la decisión documentada y comunicada."}],"resumen":["Los **objetivos** del programa deben ser concretos y salir de riesgos, requisitos y cambios.","La **extensión** fija alcance, frecuencia, duración y método de cada auditoría.","Sin **recursos** estimados y aprobados, el programa no se cumple."],"referencias":[{"cita":"ISO. ISO 19011:2026 Directrices para la auditoría de sistemas de gestión (4.ª edición, mayo de 2026; reemplaza a la ISO 19011:2018).","url":"https://www.iso.org/standard/19011"},{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"INVIMA. Resolución 1160 de 2016, texto compilado con sus modificaciones (normograma).","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm"}],"imagenes":[{"ubicacion":"Junto al proceso","descripcion":"Tablero ilustrado con un calendario anual, íconos de áreas de la planta y de proveedores, y un medidor de horas de auditoría disponibles.","alt":"Programa anual de auditoría con objetivos, extensión y recursos"}],"keywords":["objetivos del programa de auditoría","cómo hacer un programa de auditoría","alcance de auditoría","recursos para auditoría interna","programa anual de auditoría bpm","plan y programa de auditoría interna"],"mapa":{"centro":"Establecer el programa","ramas":[{"titulo":"Entradas","icono":"Database","nodos":["Requisitos regulatorios","Resultados de auditorías previas","Cambios y riesgos"]},{"titulo":"Objetivos","icono":"Target","nodos":["Cumplimiento de BPM","Proveedores críticos","Preparar la certificación"]},{"titulo":"Extensión","icono":"Layers","nodos":["Alcance y frecuencia","Duración","Método en sitio, remoto o híbrido"]},{"titulo":"Recursos","icono":"Users","nodos":["Auditores competentes","Tiempo y presupuesto","Tecnología"]}]},"proceso":{"titulo":"Armar el programa anual en seis pasos","intro":"","pasos":[{"titulo":"Reúne las entradas","detalle":"Requisitos, resultados previos, desviaciones, quejas, cambios planeados y calendario regulatorio.","icono":"Database","evidencia":"Resumen de entradas del programa."},{"titulo":"Define objetivos","detalle":"Escribe tres a cinco objetivos concretos y verificables para el periodo.","icono":"Target","evidencia":"Objetivos aprobados."},{"titulo":"Evalúa riesgos del programa","detalle":"Identifica qué puede impedir lograr los objetivos y cómo mitigarlo.","icono":"AlertTriangle","evidencia":"Matriz de riesgos del programa."},{"titulo":"Fija la extensión","detalle":"Asigna auditorías con alcance, frecuencia, duración y método.","icono":"Layers","evidencia":"Calendario con alcance por auditoría."},{"titulo":"Estima recursos","detalle":"Calcula horas, personas, expertos, viajes y tecnología.","icono":"Calculator","evidencia":"Presupuesto y asignación de auditores."},{"titulo":"Aprueba y comunica","detalle":"Presenta el programa a la dirección y comunícalo a las áreas.","icono":"Signature","evidencia":"Programa aprobado y divulgado."}]},"caso":{"titulo":"Lanzamiento con proveedores nuevos","contexto":"Un laboratorio planea lanzar en septiembre un producto con un principio activo de un fabricante nuevo en India y un material de envase de un proveedor nacional también nuevo. Su programa de auditoría ya está aprobado y no incluye a ninguno de los dos.","pregunta":"¿Qué debe hacer quien gestiona el programa?","opciones":[{"texto":"Esperar al programa del próximo año, porque el actual ya fue aprobado.","correcta":false,"retro":"El programa se ajusta cuando cambian los riesgos. Un lanzamiento con proveedores nuevos es un cambio relevante."},{"texto":"Ajustar el programa: incluir la evaluación de ambos proveedores antes del lanzamiento, decidir el método por riesgo y gestionar los recursos con la dirección.","correcta":true,"retro":"El programa es dinámico. La evaluación de proveedores críticos nuevos debe preceder a su aprobación, y el cambio se documenta."},{"texto":"Aprobar a los proveedores con sus certificados y auditar después del lanzamiento.","correcta":false,"retro":"Para un proveedor crítico nuevo, los certificados no reemplazan la evaluación basada en riesgo antes de aprobarlo."}]}}$j$::jsonb;
