  -- 19. Auditorías remotas e híbridas
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La cámara que no entró al área","texto":"Durante una auditoría remota a un fabricante de cápsulas, el guía muestra con su celular la sala de encapsulado. Todo se ve ordenado, pero la cámara nunca enfoca la parte trasera de la máquina ni el área de lavado, y cuando el auditor pide ver el diferencial de presión, la conexión «se cae». Las auditorías remotas son útiles y llegaron para quedarse, pero tienen límites que hay que conocer y gestionar."},"objetivos":["Explicar cómo ISO 19011:2026 e ISO/IEC TS 17012:2024 orientan el uso de métodos de auditoría remotos.","Decidir cuándo una auditoría puede ser remota, híbrida o debe ser en sitio, con base en el riesgo.","Aplicar buenas prácticas de tecnología, seguridad de la información y verificación de la evidencia a distancia."],"conceptos":[{"icono":"Globe","termino":"Método de auditoría remoto","definicion":"Forma de obtener y evaluar evidencia sin presencia física en el lugar, mediante tecnologías de la información y las comunicaciones: videollamadas, documentos compartidos, recorridos con cámara o análisis de datos."},{"icono":"Split","termino":"Auditoría híbrida","definicion":"Combinación de actividades en sitio y a distancia en una misma auditoría, por ejemplo revisión documental remota y verificación de áreas en sitio."},{"icono":"Database","termino":"Ubicación virtual","definicion":"Lugar donde la organización realiza trabajo o presta un servicio en un entorno en línea, como un sistema en la nube o una plataforma de trabajo remoto."},{"icono":"Lock","termino":"Seguridad de la evidencia digital","definicion":"Protección de la confidencialidad, la integridad y el acceso controlado a los documentos, grabaciones y capturas que se usan como evidencia."}],"secciones":[{"titulo":"Qué dicen las normas","parrafos":["La auditoría remota dejó de ser una excepción. La especificación técnica **ISO/IEC TS 17012:2024** orienta el uso de métodos remotos para auditar sistemas de gestión y aclara que no pretenden reemplazar los métodos en sitio, sino servir como herramienta para auditar de manera eficaz y eficiente. La **ISO 19011:2026** incorpora esa orientación: amplía su anexo A con guía sobre métodos remotos y ubicaciones virtuales, y trata los métodos en sitio, remotos e híbridos como opciones que se deciden según el riesgo.","En el ámbito regulatorio, el **Decreto 335 de 2022** permite que el INVIMA haga sus visitas de certificación, renovación y ampliación de forma presencial, virtual o mixta. Otras autoridades también han formalizado evaluaciones remotas; la FDA, por ejemplo, publicó una guía de preguntas y respuestas sobre evaluaciones regulatorias remotas. Para una empresa farmacéutica, esto significa que debe saber auditar a distancia y también **ser auditada** a distancia."]},{"titulo":"Cuándo sí y cuándo no","parrafos":["Los métodos remotos funcionan bien para la **revisión documental** (procedimientos, registros, informes de validación), las **entrevistas**, el análisis de datos y tendencias, y el seguimiento de acciones correctivas que se demuestran con evidencia documental. Son útiles cuando hay restricciones de viaje, cuando el riesgo del proveedor es bajo o medio, o como preparación para una visita en sitio más corta y enfocada.","Tienen límites claros cuando lo que se necesita verificar es **físico o de comportamiento**: condiciones de áreas limpias, flujos de personal y materiales, estado de equipos, prácticas asépticas o la integridad de los datos en los sistemas del laboratorio. La decisión se toma por riesgo y se documenta, junto con las limitaciones del método. Si durante una auditoría remota la evidencia no permite llegar a una conclusión confiable, el equipo debe decirlo y proponer una verificación en sitio."]},{"titulo":"Buenas prácticas para auditar a distancia","parrafos":["Antes: verificar con el auditado la **capacidad tecnológica** (plataforma, conexión, cámara móvil, acceso a sistemas), hacer una prueba, acordar las reglas de **seguridad de la información** (qué se comparte, por qué canal, si se permite grabar o tomar capturas, cuándo se eliminan) y preparar un plan alternativo si falla la conexión. El plan de auditoría debe indicar qué actividades serán remotas y cuáles en sitio.","Durante: pedir que la cámara muestre lo que el equipo solicita, no lo que el guía elige; solicitar documentos en tiempo real y no solo los preparados con anticipación; verificar la identidad de las personas entrevistadas; y tomar pausas, porque la fatiga es mayor a distancia. Después: el informe debe declarar los **métodos usados** y sus limitaciones. Una conexión que «se cae» justo ante cierta evidencia es, en sí misma, un dato que el equipo debe registrar."]}],"errores":[{"error":"Elegir auditoría remota solo por costo.","correccion":"Decide por riesgo y por la evidencia que necesitas verificar."},{"error":"Grabar sin acuerdo previo.","correccion":"Acuerda grabaciones, capturas y su eliminación desde la preparación."},{"error":"Omitir en el informe los límites del método.","correccion":"Declara siempre los métodos usados y lo que no se pudo verificar."}],"comprueba":[{"pregunta":"¿Qué especificación técnica orienta los métodos de auditoría remotos?","respuesta":"La ISO/IEC TS 17012:2024, cuya guía incorpora la ISO 19011:2026."},{"pregunta":"¿Para qué funcionan bien los métodos remotos?","respuesta":"Revisión documental, entrevistas, análisis de datos y seguimiento de acciones con evidencia documental."},{"pregunta":"¿Cómo puede hacer el INVIMA sus visitas de certificación según el Decreto 335 de 2022?","respuesta":"De forma presencial, virtual o mixta."}],"resumen":["Los métodos remotos son **una herramienta, no un reemplazo**, según ISO/IEC TS 17012 e ISO 19011:2026.","Lo físico y lo conductual suelen exigir **presencia**; decide por riesgo.","Prueba la tecnología, protege la **evidencia digital** y declara los **límites** en el informe."],"referencias":[{"cita":"ISO. ISO 19011:2026 Directrices para la auditoría de sistemas de gestión (4.ª edición, mayo de 2026; reemplaza a la ISO 19011:2018).","url":"https://www.iso.org/standard/19011"},{"cita":"ISO/CASCO. ISO/IEC TS 17012:2024 Conformity assessment — Guidelines for the use of remote auditing methods in auditing management systems.","url":"https://www.iso.org/standard/84718.html"},{"cita":"ISO/TC 176. ISO 19011:2026 Released! (9 de junio de 2026).","url":"https://committee.iso.org/sites/tc176/home/news/content-left-area/news-and-updates/iso-19011-2026-released.html"},{"cita":"INVIMA. Decreto 335 de 2022, texto compilado (normograma): procedimiento para obtener los certificados de buenas prácticas de elaboración, laboratorio y manufactura.","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/decreto_0335_2022.htm"}],"imagenes":[{"ubicacion":"Junto a la situación inicial","descripcion":"Pantalla de videollamada ilustrada con una sala de encapsulado vista desde un celular, un recuadro con documentos compartidos y un candado que representa la seguridad de la información.","alt":"Auditoría remota a un fabricante farmacéutico con evidencia compartida en línea"}],"keywords":["auditoría remota","auditoría híbrida","iso iec ts 17012","iso 19011 2026 auditoría remota","visita virtual invima","cómo hacer una auditoría remota a proveedores"],"mapa":{"centro":"Auditar a distancia","ramas":[{"titulo":"Referencias","icono":"BookOpen","nodos":["ISO 19011:2026","ISO/IEC TS 17012:2024","Decreto 335: visitas virtuales o mixtas"]},{"titulo":"Funciona bien para","icono":"CheckCircle2","nodos":["Revisión documental","Entrevistas","Análisis de datos"]},{"titulo":"Tiene límites en","icono":"AlertTriangle","nodos":["Condiciones físicas de áreas","Comportamiento en operación","Verificación de integridad en sitio"]},{"titulo":"Requisitos","icono":"Lock","nodos":["Prueba de la tecnología","Seguridad de la información","Plan alternativo"]}]},"proceso":{"titulo":"Decidir y preparar una auditoría remota","intro":"","pasos":[{"titulo":"Evalúa el riesgo","detalle":"Qué evidencia se necesita y si se puede obtener de forma confiable a distancia.","icono":"Gauge","evidencia":"Justificación del método."},{"titulo":"Verifica la capacidad del auditado","detalle":"Plataforma, conexión, cámara móvil y acceso a sistemas.","icono":"Cpu","evidencia":"Prueba técnica realizada."},{"titulo":"Acuerda la seguridad","detalle":"Canales, grabaciones, capturas, conservación y eliminación de evidencia.","icono":"Lock","evidencia":"Reglas de seguridad acordadas."},{"titulo":"Planifica en detalle","detalle":"Actividades remotas y en sitio, tiempos, pausas y plan alternativo.","icono":"CalendarClock","evidencia":"Plan de auditoría híbrido o remoto."},{"titulo":"Ejecuta y verifica","detalle":"Pide en tiempo real y dirige la cámara a lo que necesitas ver.","icono":"Scan","evidencia":"Evidencia obtenida y verificada."},{"titulo":"Declara limitaciones","detalle":"El informe indica los métodos y lo que no se pudo verificar.","icono":"FileText","evidencia":"Informe con métodos y límites."}]},"caso":{"titulo":"Proveedor de estériles en otro continente","contexto":"Un laboratorio necesita reevaluar a su fabricante por contrato de inyectables, ubicado en otro continente. El presupuesto de viajes está congelado y el proveedor propone una auditoría totalmente remota. En la última auditoría en sitio hubo hallazgos en prácticas asépticas.","pregunta":"¿Qué decisión es más defendible?","opciones":[{"texto":"Auditoría totalmente remota, porque ISO 19011:2026 la acepta como método válido.","correcta":false,"retro":"La norma la acepta como opción, pero la decisión es por riesgo. Con hallazgos previos en prácticas asépticas, la evidencia física es indispensable."},{"texto":"Auditoría híbrida: revisión documental y entrevistas remotas ahora, y verificación en sitio de las áreas asépticas tan pronto sea posible, con el riesgo documentado.","correcta":true,"retro":"Combina eficiencia con la evidencia física que exige el riesgo, y deja trazable la decisión y sus limitaciones."},{"texto":"Aplazar la reevaluación hasta que haya presupuesto.","correcta":false,"retro":"Aplazar sin medidas deja sin control a un proveedor de alto riesgo con hallazgos previos."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Auditorías remotas e híbridas$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Auditorías remotas e híbridas$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 20. Introducción a la unidad: de la evidencia a la mejora
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Treinta hallazgos y ningún cambio","texto":"Un laboratorio guarda en una carpeta compartida los informes de sus autoinspecciones de los últimos cuatro años: más de cien hallazgos. Al revisarlos, la nueva directora de calidad descubre que el 40 % se repite de un año a otro, que la mitad de los planes de acción dicen «capacitar al personal» y que ninguno tiene verificación de eficacia. La empresa auditaba, pero no mejoraba. Esta unidad trata justamente del tramo que convierte la evidencia en mejora."},"objetivos":["Describir el recorrido desde la evidencia hasta la mejora: hallazgo, clasificación, cierre, informe, acciones y verificación de eficacia.","Relacionar el resultado de la auditoría con el sistema de acciones correctivas y preventivas (CAPA).","Reconocer los indicadores que muestran si las auditorías generan mejora real."],"conceptos":[{"icono":"Flag","termino":"Hallazgo","definicion":"Resultado de comparar la evidencia con los criterios: conformidad, no conformidad u oportunidad de mejora, y a veces una buena práctica que vale la pena difundir."},{"icono":"Tag","termino":"Clasificación","definicion":"Calificación del hallazgo según su riesgo (crítico, mayor o menor) que define la prioridad y los plazos de respuesta."},{"icono":"Wrench","termino":"Acción correctiva","definicion":"Acción para eliminar la causa de una no conformidad y evitar que vuelva a ocurrir. Se distingue de la corrección, que solo arregla el efecto inmediato."},{"icono":"CheckCircle2","termino":"Verificación de eficacia","definicion":"Comprobación, con evidencia y después de un tiempo razonable, de que la acción eliminó la causa y el problema no se repite."}],"secciones":[{"titulo":"Por qué tantas auditorías no producen mejora","parrafos":["Las fallas más comunes después de la ejecución son cuatro: hallazgos mal redactados, que el área no entiende o no acepta; clasificaciones inconsistentes, que no permiten priorizar; informes tardíos o confusos; y planes de acción que atacan síntomas («capacitar», «recordar», «reforzar») sin análisis de causa ni verificación de eficacia. El resultado es la **recurrencia**: los mismos hallazgos, año tras año.","Las autoridades lo saben. Los análisis de hallazgos de inspección que publica la EMA muestran que las deficiencias en el sistema de calidad, la documentación y el manejo de desviaciones se repiten entre empresas y entre inspecciones. Un programa de auditoría interna eficaz debería encontrar esas debilidades antes, y su sistema de acciones debería corregirlas de fondo."]},{"titulo":"El recorrido completo","parrafos":["El recorrido tiene seis tramos. Primero, **redactar** cada hallazgo con criterio, evidencia y brecha. Segundo, **clasificarlo** por riesgo con una escala común. Tercero, presentarlo en la **reunión de cierre**, donde el auditado lo entiende y, si no está de acuerdo, se registra la divergencia. Cuarto, documentarlo en un **informe** completo, claro y oportuno. Quinto, que el auditado defina **corrección, causa raíz y acción correctiva**, con responsables y fechas. Sexto, **verificar la eficacia** antes de cerrar.","Cada tramo tiene su clase en esta unidad, que termina con la evaluación y la mejora del propio programa de auditoría. La metodología detallada de análisis de causa raíz (cinco porqués, Ishikawa, árbol de fallas) se estudia a fondo en el curso de Gestión de Desviaciones y CAPA; aquí nos concentramos en cómo quien audita evalúa la calidad de esas respuestas."]},{"titulo":"Indicadores que muestran si la auditoría sirve","parrafos":["Para saber si las auditorías generan mejora, no basta con contar cuántas se hicieron. Algunos indicadores útiles: porcentaje de hallazgos **repetidos** respecto a auditorías anteriores; porcentaje de acciones cerradas **a tiempo**; porcentaje de acciones cerradas con **verificación de eficacia** positiva; tiempo promedio de cierre por clasificación; y la **brecha de detección**, es decir, cuántos hallazgos de la inspección del INVIMA o de clientes no habían sido detectados por la autoinspección.","Estos indicadores se presentan en la revisión por la dirección y sirven para mejorar el programa. Una brecha de detección alta, por ejemplo, indica que la autoinspección necesita más profundidad, otras personas auditoras o mejores listas de verificación. Un porcentaje alto de hallazgos repetidos indica que el problema no está en auditar, sino en corregir."]}],"errores":[{"error":"Medir el programa solo por el número de auditorías realizadas.","correccion":"Mide también recurrencia, cierre a tiempo, eficacia y brecha de detección."},{"error":"Aceptar «capacitar» como acción correctiva universal.","correccion":"Exige análisis de causa raíz y acciones dirigidas a esa causa."},{"error":"Cerrar acciones sin verificar su eficacia.","correccion":"Define cómo y cuándo se comprobará que el problema no se repite."}],"comprueba":[{"pregunta":"¿Qué diferencia hay entre corrección y acción correctiva?","respuesta":"La corrección arregla el efecto inmediato; la acción correctiva elimina la causa para que no se repita."},{"pregunta":"¿Qué es la brecha de detección?","respuesta":"La proporción de hallazgos de inspecciones externas que la autoinspección no había detectado."},{"pregunta":"¿Qué indica un porcentaje alto de hallazgos repetidos?","respuesta":"Que las acciones correctivas no están atacando las causas."}],"resumen":["La mejora exige **hallazgos claros, clasificación común, cierre, informe, acciones y eficacia**.","La **recurrencia** es el síntoma de acciones que no atacan la causa.","Mide el programa con **indicadores de resultado**, no solo de actividad."],"referencias":[{"cita":"ISO. ISO 19011:2026 Directrices para la auditoría de sistemas de gestión (4.ª edición, mayo de 2026; reemplaza a la ISO 19011:2018).","url":"https://www.iso.org/standard/19011"},{"cita":"EMA. Good Manufacturing Practice: an analysis of regulatory inspection findings in the centralised procedure.","url":"https://www.ema.europa.eu/en/documents/other/good-manufacturing-practice-analysis-regulatory-inspection-findings-centralised-procedure_en.pdf"},{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Escalera ilustrada de seis peldaños: hallazgo, clasificación, cierre, informe, acción correctiva y verificación de eficacia, con una flecha que vuelve al programa.","alt":"Recorrido desde el hallazgo de auditoría hasta la verificación de eficacia"}],"keywords":["hallazgos de auditoría","de la auditoría a la mejora continua","indicadores de auditoría interna","recurrencia de hallazgos","verificación de eficacia capa","acciones correctivas de auditoría"],"mapa":{"centro":"De la evidencia a la mejora","ramas":[{"titulo":"Hallazgos","icono":"Flag","nodos":["Redacción con criterio y evidencia","Clasificación por riesgo","Buenas prácticas"]},{"titulo":"Cierre e informe","icono":"FileText","nodos":["Reunión de cierre","Informe completo y claro","Distribución oportuna"]},{"titulo":"Acciones","icono":"Wrench","nodos":["Corrección","Causa raíz","Acción correctiva"]},{"titulo":"Eficacia","icono":"CheckCircle2","nodos":["Verificación con evidencia","Hallazgos no repetidos","Mejora del programa"]}]},"caso":{"titulo":"El plan de acción de siempre","contexto":"Ante un hallazgo mayor por registros de limpieza firmados antes de ejecutar la tarea, el área responde con un plan: «Capacitar al personal en el procedimiento de limpieza. Responsable: supervisor. Fecha: 30 días». Es la tercera vez que el hallazgo aparece en dos años.","pregunta":"¿Cómo debe evaluarlo quien audita?","opciones":[{"texto":"Aceptarlo, porque tiene responsable y fecha.","correcta":false,"retro":"Responsable y fecha no bastan. Un hallazgo repetido tres veces con la misma acción demuestra que la acción no ataca la causa."},{"texto":"No aceptarlo como suficiente: pedir análisis de causa raíz (presión de tiempos, diseño del formato, supervisión, cultura), acciones dirigidas a esa causa y un criterio de verificación de eficacia.","correcta":true,"retro":"La recurrencia es la prueba de que la capacitación sola no resolvía la causa. Quien audita debe evaluar la calidad del plan, no solo su forma."},{"texto":"Escalar el hallazgo a crítico y sancionar al supervisor.","correcta":false,"retro":"La clasificación se basa en el riesgo, no en el castigo. Lo que falta es un análisis de causa y acciones eficaces."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: de la evidencia a la mejora$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción a la unidad: de la evidencia a la mejora$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 21. Redacción de hallazgos: no conformidad, observación y oportunidad de mejora
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Un hallazgo que nadie pudo discutir","texto":"Compara dos redacciones. Primera: «El laboratorio no controla bien sus reactivos». Segunda: «Criterio: el procedimiento PL-LAB-021 exige rotular los reactivos preparados con fecha de preparación, vencimiento y responsable. Evidencia: el 12 de mayo, en la mesa 3 del laboratorio fisicoquímico, cuatro de diez frascos de reactivos preparados no tenían fecha de vencimiento, entre ellos la fase móvil usada en la valoración del lote 24-117. Brecha: reactivos sin vencimiento en uso para análisis de liberación». La primera abre una discusión; la segunda abre una investigación."},"objetivos":["Redactar hallazgos con la estructura criterio, evidencia y brecha, sin opiniones ni nombres de personas.","Diferenciar no conformidad, observación y oportunidad de mejora, y registrar buenas prácticas.","Revisar la calidad de un hallazgo con una lista de verificación antes de presentarlo."],"conceptos":[{"icono":"XCircle","termino":"No conformidad","definicion":"Incumplimiento de un requisito: la evidencia muestra que un criterio no se cumple. Requiere corrección y, normalmente, acción correctiva."},{"icono":"Eye","termino":"Observación","definicion":"Término que muchos programas usan para una situación que todavía no incumple, pero que podría llevar a un incumplimiento si no se atiende. Su significado debe definirse en el procedimiento."},{"icono":"Lightbulb","termino":"Oportunidad de mejora","definicion":"Aspecto que cumple, pero que podría hacerse de forma más eficaz o eficiente. No obliga a una acción correctiva."},{"icono":"Award","termino":"Buena práctica","definicion":"Forma de trabajo destacable que vale la pena reconocer y extender a otras áreas."}],"secciones":[{"titulo":"La estructura que hace defendible un hallazgo","parrafos":["Un hallazgo de no conformidad tiene tres partes. El **criterio**: qué se exige, con la referencia exacta (norma y numeral, procedimiento con su código y versión, especificación o cláusula del acuerdo de calidad). La **evidencia**: qué se encontró, con datos que cualquiera pueda verificar (lugar, fecha, documento, lote, equipo, cantidad revisada). La **brecha**: la diferencia entre lo exigido y lo encontrado, descrita con hechos y, cuando ayuda, su alcance e impacto potencial.","Algunas reglas de redacción: escribir en lenguaje claro y objetivo; no usar adjetivos («grave», «deficiente», «desordenado»); no nombrar personas, sino cargos o funciones; indicar la muestra («cuatro de diez frascos», «dos de cinco registros»); no proponer la solución, porque esa es tarea del auditado; y redactar de forma que una persona que no estuvo en la auditoría entienda el hallazgo. ISO 19011 pide además que los hallazgos de no conformidad se revisen con el auditado para confirmar que la evidencia es exacta y que se entienden."]},{"titulo":"No conformidad, observación y oportunidad de mejora","parrafos":["Según ISO 19011, los hallazgos pueden indicar **conformidad** o **no conformidad**, y además pueden llevar a identificar riesgos, oportunidades de mejora o buenas prácticas. La **no conformidad** exige que exista un requisito incumplido y una evidencia que lo demuestre. Si falta cualquiera de los dos, no hay no conformidad.","El término **observación** no tiene una definición única: algunas empresas lo usan para riesgos que aún no son incumplimientos, otras para no conformidades menores. Por eso el procedimiento de auditoría debe definir con precisión cada categoría y su tratamiento. La **oportunidad de mejora** reconoce algo que cumple pero podría hacerse mejor, y la **buena práctica** destaca algo que otras áreas podrían copiar. Incluir buenas prácticas en el informe equilibra la visión de la auditoría y motiva a las áreas."]},{"titulo":"Errores típicos y cómo corregirlos","parrafos":["Hallazgo sin criterio: «Los operarios no usan bien la cofia». ¿Qué requisito? Corrección: citar el numeral de vestuario del procedimiento de ingreso a áreas. Hallazgo sin evidencia: «No siempre se registra la temperatura». ¿Cuándo, dónde, cuántas veces? Corrección: «De 30 días revisados en marzo, el registro de temperatura de la bodega 2 está vacío en 6 días (5, 6, 12, 13, 19 y 20 de marzo)».","Hallazgo que culpa: «La analista María no sabe hacer la prueba». Corrección: describir el hecho («la persona que ejecutó el ensayo de disolución del lote X no tiene registro de entrenamiento en el método vigente»). Hallazgo que propone la solución: «Se debe comprar un nuevo termohigrómetro». Corrección: describir el incumplimiento y dejar que el auditado determine la causa y la acción. Un hallazgo bien escrito ahorra discusiones en el cierre y orienta la investigación."]}],"errores":[{"error":"Escribir hallazgos con adjetivos y generalizaciones.","correccion":"Describe hechos con la muestra revisada: «4 de 10», «6 de 30 días»."},{"error":"Nombrar a la persona responsable del error.","correccion":"Usa cargos o funciones; la auditoría evalúa procesos."},{"error":"Declarar no conformidad sin requisito incumplido.","correccion":"Si no hay criterio incumplido, clasifícalo como observación de riesgo u oportunidad de mejora."}],"comprueba":[{"pregunta":"¿Qué tres partes tiene un hallazgo de no conformidad?","respuesta":"Criterio, evidencia y brecha."},{"pregunta":"¿Qué condición es necesaria para una no conformidad?","respuesta":"Que exista un requisito incumplido demostrado con evidencia objetiva."},{"pregunta":"¿Por qué incluir buenas prácticas en el informe?","respuesta":"Porque equilibran la visión de la auditoría, motivan a las áreas y permiten extender lo que funciona."}],"resumen":["Hallazgo = **criterio + evidencia + brecha**, sin adjetivos, nombres ni soluciones.","Sin requisito incumplido **no hay no conformidad**.","Define en tu procedimiento qué significa **observación** y registra también **buenas prácticas**."],"referencias":[{"cita":"ISO. ISO 19011:2026 Directrices para la auditoría de sistemas de gestión (4.ª edición, mayo de 2026; reemplaza a la ISO 19011:2018).","url":"https://www.iso.org/standard/19011"},{"cita":"ISO. ISO 9000:2026 Gestión de la calidad — Fundamentos y vocabulario (5.ª edición, mayo de 2026; reemplaza a la ISO 9000:2015).","url":"https://www.iso.org/standard/9000"},{"cita":"INVIMA. Resolución 1160 de 2016, texto compilado con sus modificaciones (normograma).","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm"}],"imagenes":[{"ubicacion":"Junto a la situación inicial","descripcion":"Dos tarjetas ilustradas lado a lado: una con una frase vaga tachada y otra con los bloques criterio, evidencia y brecha marcados en colores.","alt":"Comparación entre un hallazgo vago y un hallazgo bien redactado"}],"keywords":["cómo redactar un hallazgo de auditoría","no conformidad observación oportunidad de mejora","redacción de no conformidades","estructura de un hallazgo","ejemplos de hallazgos de auditoría bpm","diferencia entre observación y no conformidad"],"mapa":{"centro":"Un buen hallazgo","ramas":[{"titulo":"Criterio","icono":"Ruler","nodos":["Norma y numeral","Procedimiento y versión","Especificación o acuerdo"]},{"titulo":"Evidencia","icono":"FileSearch","nodos":["Qué se vio","Dónde y cuándo","Documento, lote o equipo"]},{"titulo":"Brecha","icono":"Scale","nodos":["Qué no se cumple","Alcance observado","Impacto potencial"]},{"titulo":"Tipo","icono":"Tag","nodos":["No conformidad","Observación","Oportunidad de mejora o buena práctica"]}]},"proceso":{"titulo":"Revisar un hallazgo antes de presentarlo","intro":"","pasos":[{"titulo":"¿Tiene criterio exacto?","detalle":"Norma y numeral, o procedimiento con código y versión.","icono":"Ruler","evidencia":"Referencia completa."},{"titulo":"¿La evidencia es verificable?","detalle":"Lugar, fecha, documento, lote o equipo, y muestra revisada.","icono":"FileSearch","evidencia":"Datos que cualquiera puede comprobar."},{"titulo":"¿La brecha es un hecho?","detalle":"Sin adjetivos ni suposiciones.","icono":"Scale","evidencia":"Brecha descrita objetivamente."},{"titulo":"¿Evita nombres y soluciones?","detalle":"Cargos en lugar de nombres; sin proponer la acción.","icono":"Users","evidencia":"Redacción neutral."},{"titulo":"¿Se revisó con el auditado?","detalle":"Se mostró la evidencia y se confirmó su exactitud.","icono":"CheckCircle2","evidencia":"Hallazgo reconocido o divergencia anotada."}]},"caso":{"titulo":"¿No conformidad u oportunidad de mejora?","contexto":"En el almacén, la temperatura está controlada y registrada dentro de los límites todos los días del periodo revisado. Sin embargo, el registro es manual dos veces al día, y no hay alarma que avise si la temperatura sube durante la noche o el fin de semana. El procedimiento vigente exige solo los dos registros diarios.","pregunta":"¿Cómo se clasifica?","opciones":[{"texto":"No conformidad, porque no hay alarma.","correcta":false,"retro":"No hay requisito incumplido: el procedimiento exige dos registros diarios y se cumplen."},{"texto":"Oportunidad de mejora u observación de riesgo, según la definición del procedimiento: cumple, pero hay un riesgo de no detectar excursiones fuera del horario de registro.","correcta":true,"retro":"Sin requisito incumplido no hay no conformidad. Pero el riesgo existe y vale la pena señalarlo para que el área lo evalúe."},{"texto":"No se registra nada, porque todo está dentro de límites.","correcta":false,"retro":"Identificar riesgos y oportunidades también es parte del valor de la auditoría."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Redacción de hallazgos: no conformidad, observación y oportunidad de mejora$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Redacción de hallazgos: no conformidad, observación y oportunidad de mejora$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 22. Clasificación de hallazgos: crítico, mayor y menor
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El mismo hallazgo, tres calificaciones","texto":"En un taller de auditores internos, tres personas reciben el mismo caso: una balanza analítica usada durante dos semanas con la verificación diaria vencida. Una lo califica como menor, otra como mayor y la tercera como crítico. Ninguna está necesariamente equivocada sin más contexto, pero un programa en el que cada auditor clasifica a su manera no permite priorizar ni comparar. La consistencia se construye con criterios comunes y ejemplos."},"objetivos":["Aplicar las definiciones de deficiencia crítica, mayor y menor usadas en la inspección farmacéutica.","Usar criterios de impacto, alcance, recurrencia e integridad para decidir la clasificación.","Construir una tabla de clasificación con ejemplos para lograr consistencia entre auditores."],"conceptos":[{"icono":"XCircle","termino":"Deficiencia crítica","definicion":"Deficiencia que ha producido, o conlleva un riesgo significativo de producir, un producto perjudicial para el paciente. También se considera crítica la evidencia de fraude, tergiversación o falsificación de productos o datos."},{"icono":"AlertTriangle","termino":"Deficiencia mayor","definicion":"Deficiencia no crítica que ha producido o puede producir un producto que no cumple con su autorización, o que indica una desviación importante de las BPM, o una combinación de varias deficiencias menores que juntas representan una falla mayor."},{"icono":"Tag","termino":"Deficiencia menor","definicion":"Deficiencia que no puede clasificarse como crítica ni mayor, pero que indica un apartamiento de las BPM. El PIC/S la llama «otra deficiencia»."},{"icono":"Repeat","termino":"Escalamiento","definicion":"Elevación de la clasificación por recurrencia, por alcance sistémico o por varias deficiencias relacionadas que juntas revelan una falla mayor."}],"secciones":[{"titulo":"Las definiciones de referencia","parrafos":["La guía **PI 040-1** del PIC/S, vigente desde 2019, propone un enfoque basado en riesgo para clasificar las deficiencias de BPM en tres categorías: **crítica**, **mayor** y **otra** (que en Colombia y en muchos programas se llama **menor**). Las definiciones son las que aparecen en los conceptos de esta clase, y coinciden con la lógica que siguen las guías de inspección colombianas y el curso de BPM de Edvanta.","La misma guía advierte dos cosas importantes. Primera: la clasificación no es mecánica; el contexto del hallazgo y el historial de calidad del sitio deben considerarse. Segunda: varias deficiencias relacionadas, ninguna mayor por sí sola, pueden representar juntas una deficiencia mayor, y así deben explicarse y reportarse. Una discrepancia aislada y sin impacto puede tratarse como un comentario y no como una deficiencia formal."]},{"titulo":"Cuatro preguntas para decidir","parrafos":["**¿Cuál es el impacto potencial en el paciente y en el producto?** Un riesgo de contaminación cruzada con un producto de alta potencia o un producto estéril sin garantía de esterilidad apuntan a crítico; un registro aislado sin fecha, a menor. **¿Cuál es el alcance?** Un hecho puntual pesa menos que un patrón repetido en varias áreas o lotes, que revela una falla del sistema. **¿Hay recurrencia?** Un hallazgo menor que se repite después de una acción correctiva puede escalar a mayor, porque demuestra que el sistema CAPA no funciona.","**¿Hay falta de integridad?** La falsificación, la manipulación o la destrucción de datos se clasifica normalmente como crítica, aunque el producto haya cumplido, porque destruye la confianza en todos los resultados. Volviendo al ejemplo inicial: la balanza con verificación vencida es menor si se usó para pesajes no críticos y hay evidencia posterior de su exactitud; puede ser mayor si se usó para dispensar principios activos de lotes ya liberados sin evaluar el impacto; y sería crítica si alguien registró verificaciones que no se hicieron."]},{"titulo":"La tabla de clasificación del programa","parrafos":["Para que distintas personas auditoras lleguen a la misma clasificación, el procedimiento de auditoría debe incluir una **tabla de clasificación** con las definiciones, las preguntas de decisión y ejemplos reales por área: producción, control de calidad, almacenamiento, sistemas computarizados, servicio farmacéutico. Conviene alinearla con la clasificación que usa el INVIMA en sus actas, de modo que los resultados de la autoinspección sean comparables con los de la autoridad.","La clasificación define la **respuesta**: un hallazgo crítico exige acciones inmediatas de contención (por ejemplo, detener la liberación o la distribución de lotes afectados) y comunicación urgente a la dirección; uno mayor, un plan de acción en un plazo corto con evaluación de impacto; uno menor, corrección y acción en el plazo ordinario. Los talleres periódicos de calibración entre auditores, con casos reales, son la mejor forma de mantener la consistencia."]}],"errores":[{"error":"Clasificar según la persona o el área, no según el riesgo.","correccion":"Aplica las mismas preguntas de impacto, alcance, recurrencia e integridad."},{"error":"No escalar hallazgos repetidos.","correccion":"Evalúa si la recurrencia revela una falla del sistema CAPA."},{"error":"Rebajar un hallazgo de integridad porque «el resultado era correcto».","correccion":"La falsificación de datos se trata como crítica, aunque el producto cumpla."}],"comprueba":[{"pregunta":"¿Qué hace crítica a una deficiencia?","respuesta":"Que haya producido o implique un riesgo significativo de producir un producto perjudicial, o que exista fraude o falsificación de productos o datos."},{"pregunta":"¿Cuándo varias deficiencias menores pueden ser mayores?","respuesta":"Cuando están relacionadas y juntas representan una falla importante del sistema."},{"pregunta":"¿Qué guía del PIC/S orienta la clasificación de deficiencias?","respuesta":"La PI 040-1, Guidance on Classification of GMP Deficiencies."}],"resumen":["Crítica: **riesgo significativo para el paciente o fraude**. Mayor: **desviación importante o suma de menores**. Menor: **apartamiento sin impacto esperado**.","Decide con **impacto, alcance, recurrencia e integridad**, y considera el contexto.","Una **tabla de clasificación con ejemplos** da consistencia entre auditores."],"referencias":[{"cita":"PIC/S. PI 040-1 Guidance on Classification of GMP Deficiencies (2019).","url":"https://picscheme.org/docview/2303"},{"cita":"INVIMA. Resolución 1160 de 2016, texto compilado con sus modificaciones (normograma).","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm"},{"cita":"PIC/S. PI 041: Good Practices for Data Management and Integrity in regulated GMP/GDP environments.","url":"https://picscheme.org/docview/4234"},{"cita":"ICH. Q9(R1) Quality Risk Management (2023).","url":"https://database.ich.org/sites/default/files/ICH_Q9%28R1%29_Guideline_Step4_2023_0126_0.pdf"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Semáforo ilustrado con tres niveles (crítica, mayor, menor), ejemplos breves junto a cada luz y una flecha que muestra el escalamiento por recurrencia.","alt":"Clasificación de deficiencias críticas, mayores y menores con escalamiento"}],"keywords":["clasificación de hallazgos crítico mayor menor","pics pi 040-1","deficiencia crítica bpm","clasificación de no conformidades bpm","tabla de clasificación de hallazgos","escalamiento de hallazgos por recurrencia"],"mapa":{"centro":"Clasificar por riesgo","ramas":[{"titulo":"Crítica","icono":"XCircle","nodos":["Riesgo significativo para el paciente","Fraude o falsificación de datos","Acción inmediata"]},{"titulo":"Mayor","icono":"AlertTriangle","nodos":["Producto fuera de su autorización","Desviación importante de BPM","Suma de menores"]},{"titulo":"Menor","icono":"Tag","nodos":["Apartamiento de las BPM","Sin impacto esperado aislado","Corregir y vigilar"]},{"titulo":"Para decidir","icono":"Scale","nodos":["Impacto y probabilidad","Alcance y recurrencia","Contexto e historial"]}]},"proceso":{"titulo":"Clasificar un hallazgo paso a paso","intro":"","pasos":[{"titulo":"Confirma que es deficiencia","detalle":"Hay requisito incumplido y evidencia objetiva.","icono":"CheckCircle2","evidencia":"Hallazgo bien redactado."},{"titulo":"Evalúa el impacto","detalle":"¿Puede llegar al paciente o afectar el cumplimiento del registro?","icono":"Pill","evidencia":"Impacto potencial descrito."},{"titulo":"Revisa la integridad","detalle":"¿Hay indicios de falsificación o manipulación de datos?","icono":"Fingerprint","evidencia":"Evaluación de integridad."},{"titulo":"Mide alcance y recurrencia","detalle":"¿Es puntual o sistémico? ¿Se repite tras una acción correctiva?","icono":"Repeat","evidencia":"Historial consultado."},{"titulo":"Compara con la tabla","detalle":"Usa definiciones y ejemplos del procedimiento.","icono":"ClipboardList","evidencia":"Clasificación justificada."},{"titulo":"Define la respuesta","detalle":"Contención inmediata, plazo y nivel de comunicación según la clase.","icono":"Hand","evidencia":"Respuesta acorde a la clasificación."}]},"caso":{"titulo":"La conciliación que no cuadró","contexto":"En la revisión de registros de envase de un antihipertensivo, el auditor encuentra que en tres lotes del último trimestre la conciliación de etiquetas impresas tuvo diferencias fuera del límite, y en ninguno se abrió desviación ni se investigó. Los lotes fueron liberados y distribuidos.","pregunta":"¿Cuál es la clasificación más defendible?","opciones":[{"texto":"Menor, porque no hay quejas de mercado.","correcta":false,"retro":"La ausencia de quejas no elimina el riesgo. Las etiquetas faltantes no investigadas pueden indicar mezclas de etiquetado."},{"texto":"Mayor como mínimo: falla repetida en un control crítico, con lotes liberados sin investigar; podría ser crítica si se demuestra riesgo de mezcla. Se exige evaluación de impacto inmediata en los lotes distribuidos.","correcta":true,"retro":"La conciliación de material impreso es un control crítico contra las mezclas. Su falla repetida sin investigación revela una desviación importante del sistema, y el impacto en mercado debe evaluarse de inmediato."},{"texto":"Oportunidad de mejora en el procedimiento de conciliación.","correcta":false,"retro":"Hay un requisito incumplido y un riesgo para el paciente; no es una oportunidad de mejora."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
