  END IF;

  -- 27. Introducción a la unidad: auditar el servicio farmacéutico y prepararse para la autoridad
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Tres autoridades, un mismo servicio","texto":"El servicio farmacéutico de un hospital de Cali recibe en un mismo semestre tres visitas: la secretaría departamental de salud verifica la habilitación del servicio; el INVIMA revisa la central de mezclas para renovar su certificado de buenas prácticas de elaboración; y la Superintendencia Nacional de Salud pide información tras una queja por fallas en la entrega de medicamentos. Cada una mira algo distinto. Quien coordina la calidad del servicio necesita saber quién vigila qué, y auditar con esos mismos ojos."},"objetivos":["Identificar las autoridades que ejercen inspección, vigilancia y control sobre servicios y establecimientos farmacéuticos.","Aplicar lo aprendido en el curso a la auditoría del servicio farmacéutico y de los establecimientos minoristas.","Reconocer la ruta de la unidad: auditar servicios, prepararse para la visita, atenderla y practicar con un simulacro."],"conceptos":[{"icono":"Landmark","termino":"Entidades territoriales de salud","definicion":"Secretarías departamentales, distritales y municipales que, según la Resolución 1403 de 2007, habilitan los servicios farmacéuticos y autorizan el funcionamiento de droguerías, farmacias-droguerías, depósitos y agencias."},{"icono":"Stamp","termino":"INVIMA","definicion":"Certifica las buenas prácticas de elaboración de los servicios que hacen preparaciones magistrales, mezclas oncológicas y reempaque en dosis unitaria, entre otros, y vigila a esos establecimientos."},{"icono":"Scale","termino":"Superintendencia Nacional de Salud","definicion":"Según la Resolución 1403, ejerce la vigilancia sobre las fallas que se presenten en el servicio farmacéutico de los prestadores de servicios de salud."},{"icono":"ClipboardCheck","termino":"Autoauditoría preventiva","definicion":"Auditoría interna periódica que usa los mismos criterios e instrumentos de la autoridad para corregir antes de la visita."}],"secciones":[{"titulo":"Quién vigila qué","parrafos":["La Resolución 1403 de 2007 distribuye la inspección, vigilancia y control del servicio farmacéutico. Las **entidades territoriales de salud** habilitan los servicios farmacéuticos de los prestadores y autorizan el funcionamiento de los establecimientos farmacéuticos como droguerías, farmacias-droguerías, depósitos y agencias. El **INVIMA** certifica las buenas prácticas de elaboración de los servicios que hacen preparaciones magistrales, mezclas de medicamentos oncológicos y reempaque en el sistema de distribución de medicamentos en dosis unitaria, y esos establecimientos quedan bajo su vigilancia. La **Superintendencia Nacional de Salud** vigila las fallas del servicio farmacéutico de los prestadores.","Para la auditoría interna, esto define los criterios y los instrumentos: el servicio farmacéutico hospitalario se audita con el Decreto 780 de 2016, la Resolución 1403 de 2007 y los requisitos de habilitación; la central de mezclas, además, con las buenas prácticas de elaboración y el procedimiento de certificación del Decreto 335 de 2022; y la droguería, con los instrumentos de verificación de la secretaría de salud de su jurisdicción, que suelen publicarse como procedimientos o actas de inspección."]},{"titulo":"Auditar con los ojos de la autoridad","parrafos":["Todo lo aprendido en el curso aplica aquí: programa basado en riesgos, plan, listas de verificación orientadas a evidencia, entrevistas a quien ejecuta, recorrido siguiendo el flujo, muestreo elegido por quien audita, hallazgos con criterio y evidencia, clasificación, informe y verificación de eficacia. La diferencia está en los **criterios**: los procesos generales y especiales de la Resolución 1403, las condiciones esenciales de infraestructura, dotación y recurso humano, y el sistema de gestión de la calidad que la norma exige.","Una práctica que da muy buenos resultados es obtener el **instrumento de verificación** que usa la autoridad territorial (por ejemplo, el procedimiento de inspección a establecimientos farmacéuticos que publica una gobernación) y convertirlo en la lista de autoauditoría, agregando los requisitos internos y los compromisos de visitas anteriores. Así, la visita de la autoridad deja de ser una sorpresa."]},{"titulo":"La ruta de la unidad","parrafos":["Las dos clases siguientes aplican la auditoría al **servicio farmacéutico hospitalario y ambulatorio** y a las **droguerías y establecimientos minoristas**. Después, tres clases preparan para la visita de certificación del INVIMA: la **preparación previa** con una autoinspección integral y el alistamiento documental; la **atención durante la visita**, el acta y el plan de mejoramiento; y un **caso integrador** en el que harás un simulacro de inspección de BPM de principio a fin.","Al terminar la unidad podrás diseñar la autoauditoría de un servicio farmacéutico o de una cadena de droguerías, y liderar la preparación de una planta o de una central de mezclas para su visita de certificación o renovación."]}],"errores":[{"error":"Auditar todos los servicios con un único instrumento.","correccion":"Usa los criterios de la autoridad que corresponde a cada proceso o establecimiento."},{"error":"Pensar que la habilitación cubre las preparaciones especiales.","correccion":"Verifica si el proceso requiere certificado de buenas prácticas de elaboración del INVIMA."},{"error":"Esperar la visita para conocer el instrumento de la autoridad.","correccion":"Consíguelo y conviértelo en tu lista de autoauditoría."}],"comprueba":[{"pregunta":"¿Quién autoriza el funcionamiento de una droguería?","respuesta":"La entidad territorial de salud, según la Resolución 1403 de 2007."},{"pregunta":"¿Qué procesos del servicio farmacéutico certifica el INVIMA?","respuesta":"Las buenas prácticas de elaboración de preparaciones magistrales, mezclas oncológicas y reempaque en dosis unitaria, entre otros."},{"pregunta":"¿Qué vigila la Superintendencia Nacional de Salud en este ámbito?","respuesta":"Las fallas del servicio farmacéutico de los prestadores de servicios de salud."}],"resumen":["**Secretarías de salud**: habilitación y establecimientos. **INVIMA**: buenas prácticas de elaboración. **Supersalud**: fallas del servicio.","Audita con los **criterios e instrumentos** de la autoridad que corresponde.","La unidad termina con un **simulacro de inspección** completo."],"referencias":[{"cita":"INVIMA. Resolución 1403 de 2007, texto compilado con sus modificaciones (normograma).","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minproteccion_1403_2007.htm"},{"cita":"Ministerio de Salud y Protección Social. Decreto 780 de 2016, Decreto Único Reglamentario del sector salud.","url":"https://minsalud.gov.co/Normativa/Paginas/decreto-unico-minsalud-780-de-2016.aspx"},{"cita":"INVIMA. Decreto 335 de 2022, texto compilado (normograma): procedimiento para obtener los certificados de buenas prácticas de elaboración, laboratorio y manufactura.","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/decreto_0335_2022.htm"},{"cita":"Gobernación de Santander. Procedimiento de inspección, vigilancia y control a establecimientos farmacéuticos (MI-GS-PR-15).","url":"https://historico.santander.gov.co/intra/index.php/sig/finish/1886-medicamentos/8465-inspeccion-vigilancia-y-control-a-establecimientos-farmaceuticos-del-departamento-de-santander"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Esquema ilustrado de un servicio farmacéutico al centro con tres escudos alrededor (secretaría de salud, INVIMA y Superintendencia) y flechas que indican qué vigila cada una.","alt":"Autoridades que vigilan el servicio farmacéutico en Colombia"}],"keywords":["inspección vigilancia y control servicio farmacéutico","quién vigila las droguerías en colombia","certificación bpe invima","auditoría servicio farmacéutico colombia","resolución 1403 artículo 22","preparación visita invima"],"mapa":{"centro":"Vigilancia del servicio farmacéutico","ramas":[{"titulo":"Secretarías de salud","icono":"Landmark","nodos":["Habilitación del servicio","Autorización de droguerías","Visitas de inspección"]},{"titulo":"INVIMA","icono":"Stamp","nodos":["Buenas prácticas de elaboración","Centrales de mezclas","Decreto 335 de 2022"]},{"titulo":"Supersalud","icono":"Scale","nodos":["Fallas del servicio en IPS","Quejas de usuarios"]},{"titulo":"La organización","icono":"ClipboardCheck","nodos":["Autoauditoría","Sistema de calidad","Plan de mejoramiento"]}]},"caso":{"titulo":"La central de mezclas del hospital","contexto":"Un hospital va a abrir una central de mezclas de nutrición parenteral. El coordinador del servicio farmacéutico cree que basta con incluirla en la habilitación que verifica la secretaría departamental de salud.","pregunta":"¿Qué le falta considerar?","opciones":[{"texto":"Nada: la habilitación cubre todos los procesos del servicio.","correcta":false,"retro":"La habilitación de la entidad territorial no cubre los procesos que requieren certificación del INVIMA."},{"texto":"Que la preparación de nutrición parenteral requiere el certificado de buenas prácticas de elaboración del INVIMA, según el Decreto 335 de 2022, y que su autoauditoría debe usar esos criterios.","correcta":true,"retro":"El Decreto 335 incluye en las BPE a los servicios que preparan nutrición parenteral, y la Resolución 1403 asigna esa certificación al INVIMA."},{"texto":"Solo una notificación a la Superintendencia Nacional de Salud.","correcta":false,"retro":"La Superintendencia vigila fallas del servicio; no certifica buenas prácticas de elaboración."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: auditar el servicio farmacéutico y prepararse para la autoridad$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción a la unidad: auditar el servicio farmacéutico y prepararse para la autoridad$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 28. Auditoría al servicio farmacéutico hospitalario y ambulatorio
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La dosis que llegó a otra cama","texto":"En un hospital de mediana complejidad, una enfermera recibe en el carro de medicación la dosis unitaria de un anticoagulante rotulada para otra cama. Lo detecta antes de administrarla. La investigación muestra que el reempaque y la distribución se hacían en el mismo mesón, sin verificación independiente, y que la auditoría interna del servicio llevaba dos años revisando solo los registros de temperatura. El servicio farmacéutico tiene procesos críticos para la seguridad del paciente que la auditoría debe mirar de frente."},"objetivos":["Diseñar el alcance de una auditoría al servicio farmacéutico hospitalario y ambulatorio con base en la Resolución 1403 de 2007.","Verificar los procesos críticos: recepción, almacenamiento, distribución intrahospitalaria, dispensación y procesos especiales.","Integrar la auditoría farmacéutica con el sistema de calidad institucional y el PAMEC."],"conceptos":[{"icono":"Building2","termino":"Servicio farmacéutico hospitalario","definicion":"Servicio de atención en salud responsable de las actividades, procedimientos e intervenciones relacionadas con los medicamentos y dispositivos médicos dentro de una institución prestadora."},{"icono":"Boxes","termino":"Dosis unitaria (SDMDU)","definicion":"Sistema de distribución de medicamentos en el que cada dosis se prepara, identifica y entrega lista para administrar a un paciente específico. Su reempaque requiere certificación del INVIMA."},{"icono":"Users","termino":"Comité de Farmacia y Terapéutica","definicion":"Grupo institucional que la Resolución 1403 contempla para el servicio hospitalario, encargado, entre otras funciones, de la selección de medicamentos y de las políticas de uso."},{"icono":"ShieldCheck","termino":"PAMEC","definicion":"Programa de Auditoría para el Mejoramiento de la Calidad de la Atención en Salud, parte del Sistema Obligatorio de Garantía de Calidad, con el que se coordina el sistema de calidad del servicio farmacéutico."}],"secciones":[{"titulo":"Estructura: lo primero que se verifica","parrafos":["La auditoría empieza por las **condiciones esenciales**. En el servicio hospitalario, la Resolución 1403 exige que los servicios de mediana y alta complejidad sean dirigidos por un químico farmacéutico, y los de baja complejidad por un químico farmacéutico o un tecnólogo en regencia de farmacia. La norma fija también requisitos de infraestructura por complejidad, dotación (equipos, instrumentos, bibliografía y materiales), un Comité de Farmacia y Terapéutica y un horario de funcionamiento que no puede ser inferior a ocho horas diarias.","Estos requisitos se verifican con documentos (títulos, contratos, actas del comité, inventario de dotación, certificados de calibración) y con observación (áreas, flujos, señalización, separación de productos en cuarentena, vencidos o de control especial). Una brecha estructural, como un servicio de alta complejidad sin dirección de químico farmacéutico, afecta todo el sistema y debe tener alta prioridad en el informe."]},{"titulo":"Procesos: donde están los riesgos para el paciente","parrafos":["En la **recepción técnica** se verifica que cada ingreso compare pedido y entrega, revise cantidad, lote, vencimiento, registro sanitario y fabricante, y quede en un acta firmada por quien entrega y quien recibe. En el **almacenamiento**, que existan mecanismos para mantener la temperatura y la humedad recomendadas por el fabricante, con termómetro adecuado e higrómetro calibrado, refrigeración entre 2 °C y 8 °C para los termolábiles y un plan de emergencia ante fallas de energía, y que el lote más próximo a vencer sea el primero en salir.","En la **distribución intrahospitalaria** y la **dispensación** se audita la validación de la prescripción, la preparación y verificación de las dosis, la identificación por paciente, la entrega en el servicio y las devoluciones. Si el servicio hace **dosis unitaria**, mezclas o preparaciones magistrales, esos procesos se auditan además con las buenas prácticas de elaboración que certifica el INVIMA. En el caso inicial, una verificación independiente de las dosis reempacadas y una separación física de las tareas eran controles esperables que la auditoría debió revisar."]},{"titulo":"Ambulatorio, indicadores y PAMEC","parrafos":["En la **dispensación ambulatoria** se audita la verificación de la fórmula, la entrega completa y oportuna, la información al paciente sobre uso y conservación, el registro de salida y el manejo de pendientes. Son puntos sensibles para la satisfacción del usuario y fuente frecuente de quejas ante la Superintendencia. La auditoría debe tomar una muestra de fórmulas dispensadas y rastrearlas contra la prescripción y el registro.","La Resolución 1403 pide evaluar el servicio con **indicadores** de calidad técnica, costo, servicio, recurso humano y seguridad, y establece que, en las instituciones prestadoras, su sistema de calidad complementa el Sistema Obligatorio de Garantía de Calidad. Por eso conviene que el programa de auditoría farmacéutica se coordine con el **PAMEC** institucional: los hallazgos del servicio alimentan los planes de mejora de la institución, y los eventos adversos con medicamentos se analizan junto con farmacovigilancia y seguridad del paciente."]}],"errores":[{"error":"Auditar solo registros de temperatura y vencimientos.","correccion":"Incluye los procesos de mayor riesgo para el paciente: validación, preparación y entrega de dosis."},{"error":"Auditar el servicio de forma aislada del sistema institucional.","correccion":"Coordina con el PAMEC, seguridad del paciente y farmacovigilancia."},{"error":"Olvidar los procesos especiales que requieren certificación.","correccion":"Audita dosis unitaria, mezclas y preparaciones con las buenas prácticas de elaboración."}],"comprueba":[{"pregunta":"¿Quién debe dirigir un servicio farmacéutico de alta complejidad?","respuesta":"Un químico farmacéutico, según la Resolución 1403 de 2007."},{"pregunta":"¿Qué rango de refrigeración exige la norma para los termolábiles?","respuesta":"Entre 2 °C y 8 °C, con un plan de emergencia ante fallas de energía."},{"pregunta":"¿Con qué programa institucional se coordina la auditoría del servicio farmacéutico?","respuesta":"Con el PAMEC, dentro del Sistema Obligatorio de Garantía de Calidad."}],"resumen":["Empieza por las **condiciones esenciales**: dirección, infraestructura, dotación y horario.","Concéntrate en los procesos de **mayor riesgo para el paciente**: validación, preparación, entrega y cadena de frío.","Integra los resultados con el **PAMEC** y la seguridad del paciente."],"referencias":[{"cita":"INVIMA. Resolución 1403 de 2007, texto compilado con sus modificaciones (normograma).","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minproteccion_1403_2007.htm"},{"cita":"Ministerio de Salud y Protección Social. Decreto 780 de 2016, Decreto Único Reglamentario del sector salud.","url":"https://minsalud.gov.co/Normativa/Paginas/decreto-unico-minsalud-780-de-2016.aspx"},{"cita":"Ministerio de la Protección Social. Resolución 1403 de 2007: Modelo de Gestión del Servicio Farmacéutico y Manual de Condiciones Esenciales y Procedimientos.","url":"https://www.invima.gov.co/sites/default/files/resolucion_1403_2007.pdf"},{"cita":"INVIMA. Decreto 335 de 2022, texto compilado (normograma): procedimiento para obtener los certificados de buenas prácticas de elaboración, laboratorio y manufactura.","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/decreto_0335_2022.htm"}],"imagenes":[{"ubicacion":"Junto al proceso","descripcion":"Ilustración de un carro de dosis unitaria con gavetas rotuladas por paciente, una lupa sobre un rótulo y una lista de verificación al lado.","alt":"Auditoría a la distribución de medicamentos en dosis unitaria"}],"keywords":["auditoría servicio farmacéutico hospitalario","auditoría dispensación ambulatoria","dosis unitaria auditoría","resolución 1403 servicio hospitalario","pamec servicio farmacéutico","auditoría farmacia hospitalaria colombia"],"mapa":{"centro":"Auditar el servicio hospitalario","ramas":[{"titulo":"Estructura","icono":"Building2","nodos":["Dirección según complejidad","Infraestructura y dotación","Horario mínimo de funcionamiento"]},{"titulo":"Procesos generales","icono":"Workflow","nodos":["Recepción técnica","Almacenamiento y cadena de frío","Distribución y dispensación"]},{"titulo":"Procesos especiales","icono":"FlaskConical","nodos":["Dosis unitaria","Mezclas y preparaciones","Atención farmacéutica"]},{"titulo":"Calidad y seguridad","icono":"ShieldCheck","nodos":["Indicadores","Farmacovigilancia","Coordinación con el PAMEC"]}]},"proceso":{"titulo":"Auditar la dispensación en dosis unitaria","intro":"","pasos":[{"titulo":"Selecciona prescripciones","detalle":"Por riesgo (anticoagulantes, insulinas, alto riesgo) y al azar del día.","icono":"Crosshair","evidencia":"Muestra de prescripciones."},{"titulo":"Verifica la validación","detalle":"Revisión farmacéutica de dosis, vía, interacciones y alergias.","icono":"FileCheck","evidencia":"Registro de validación."},{"titulo":"Observa la preparación","detalle":"Reempaque, rotulado por paciente y verificación independiente.","icono":"Eye","evidencia":"Observación de la operación."},{"titulo":"Rastrea hasta la cama","detalle":"Compara la dosis entregada con la prescripción y el registro de administración.","icono":"Route","evidencia":"Trazabilidad confirmada."},{"titulo":"Revisa devoluciones y errores","detalle":"Registro de devoluciones, errores detectados y su análisis.","icono":"AlertTriangle","evidencia":"Errores analizados y acciones."}]},"caso":{"titulo":"La insulina fuera de la nevera","contexto":"En la auditoría al servicio de urgencias de un hospital, el equipo encuentra en el carro de paro dos plumas de insulina sin abrir, a temperatura ambiente, sin rótulo de fecha de salida de refrigeración. El procedimiento del servicio exige rotular la fecha en que se retira de la nevera.","pregunta":"¿Cómo se trata el hallazgo?","opciones":[{"texto":"Como oportunidad de mejora, porque las insulinas toleran un tiempo a temperatura ambiente.","correcta":false,"retro":"Sin fecha de salida no se puede saber si el producto sigue dentro del tiempo permitido. Hay un requisito incumplido."},{"texto":"Como no conformidad: el procedimiento exige rotular la fecha y sin ella no se puede garantizar la estabilidad. Corrección inmediata, evaluación de otros carros y análisis de causa.","correcta":true,"retro":"Hay criterio (procedimiento), evidencia (plumas sin rótulo) y riesgo para el paciente. La corrección y la extensión a otros servicios son parte del tratamiento."},{"texto":"Se retiran las plumas y no se registra, porque ya se corrigió.","correcta":false,"retro":"La corrección inmediata no elimina el hallazgo ni la necesidad de buscar la causa y otros casos similares."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Auditoría al servicio farmacéutico hospitalario y ambulatorio$t$ AND deleted_at IS NULL
